'use strict';
// v0.4.4: verified-email self signup for Mahidol/RFS with admin approval; retains v0.4.3 scanning workflows.
const C=window.CNMI_CONFIG||{},S={token:null,refresh:null,expire:0,email:'',role:'',view:'home',equipment:[],forms:[],rules:[],docs:[],cases:[],cal:[],years:[],plans:[],filter:'',month:new Date().toISOString().slice(0,7),selected:new Set(),uploadFile:null,scanInfo:null,pendingRows:[],importName:'',scanConflict:false,embeddedScan:null,localPages:[],localDevices:[],members:[]};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',registry:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',monthly:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M7 2v4M17 2v4M3 9h18M8 14h3"/>',scan:'<path d="M4 9V4h5M15 4h5v5M4 15v5h5M15 20h5v-5M4 12h16"/>',qr:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><path d="M14 14h3v3h-3zM21 14v7h-6"/>',cal:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/>',plans:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h4"/>',case:'<path d="M4 4h16v16H4zM8 9h8M8 13h8M8 17h5"/>',admin:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>'};
const ico=k=>`<svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.home}</svg>`;
function toast(message,error=false){let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.className='message';el.style='position:fixed;right:12px;bottom:12px;max-width:420px;z-index:30;box-shadow:0 3px 18px #103b5333';document.body.append(el);}el.textContent=message;el.className='message'+(error?' error':'');el.hidden=false;setTimeout(()=>el.hidden=true,6000);}
function validConfig(){return /^https:\/\/[^/]+\.supabase\.co\/?$/.test(C.supabaseUrl||'')&&String(C.publishableKey||'').length>15;}
function saveSession(x){S.token=x.access_token;S.refresh=x.refresh_token;S.expire=Math.floor(Date.now()/1000)+Number(x.expires_in||3600);sessionStorage.setItem('CNMI_AUTH_V040',JSON.stringify({token:S.token,refresh:S.refresh,expire:S.expire}));}
function loadSession(){try{const x=JSON.parse(sessionStorage.getItem('CNMI_AUTH_V040')||'null');if(x){S.token=x.token;S.refresh=x.refresh;S.expire=x.expire||0;}}catch{}}
function resetSession(){sessionStorage.removeItem('CNMI_AUTH_V040');S.token=null;S.refresh=null;S.role='';S.email='';}
async function authToken(){if(!S.token)throw Error('กรุณาเข้าสู่ระบบ');if(S.expire>Date.now()/1000+90)return S.token;if(!S.refresh)throw Error('เซสชันหมดอายุ');const r=await fetch(`${C.supabaseUrl}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{'apikey':C.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:S.refresh})});const j=await r.json();if(!r.ok)throw Error('เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่');saveSession(j);return S.token;}
async function api(method,path,data,opts={}){const token=await authToken();const headers={'apikey':C.publishableKey,'Authorization':`Bearer ${token}`,'Content-Type':'application/json',...(method==='POST'?{'Prefer':'return=representation'}:{}),...opts.headers};const r=await fetch(`${C.supabaseUrl}/rest/v1/${path}`,{method,headers,body:data===undefined?undefined:JSON.stringify(data)});const txt=await r.text();if(!r.ok)throw Error(`Supabase ${r.status}: ${txt.slice(0,190)}`);return txt?JSON.parse(txt):[];}
async function get(path){return api('GET',path);}
function parseUsernameInput(raw,selectedDomain){
  let local=String(raw||'').trim().toLowerCase();
  let domain=String(selectedDomain||'').trim().toLowerCase();
  if(!['mahidol.ac.th','rfs.co.th'].includes(domain))throw Error('เลือกมหิดล หรือ RFS ก่อน');
  // Support copy/paste of an entire address without appending the suffix twice.
  if(local.includes('@')){
    const bits=local.split('@');
    if(bits.length!==2||!['mahidol.ac.th','rfs.co.th'].includes(bits[1]))throw Error('รองรับเฉพาะอีเมล @mahidol.ac.th หรือ @rfs.co.th');
    domain=bits[1];local=bits[0];
  }
  if(!/^[a-z0-9._%+\-]{1,64}$/.test(local)||local.startsWith('.')||local.endsWith('.')||local.includes('..'))throw Error('กรอกชื่ออีเมลก่อน @ ให้ถูกต้อง');
  return {local,domain,email:`${local}@${domain}`};
}
function emailChoice(form){
  return parseUsernameInput(form.elements.local.value,form.elements.domain.value).email;
}
function attachEmailPreview(form){
 const local=form.elements.local,domain=form.elements.domain,preview=form.querySelector('[data-email-preview]');
 function update(){
  try{
   const raw=local.value.trim();
   if(!raw){preview.textContent='ตัวอย่าง: '+(domain.value==='rfs.co.th'?'username.s@rfs.co.th':'username.sur@mahidol.ac.th');return;}
   const parsed=parseUsernameInput(raw,domain.value);
   if(raw.includes('@')){local.value=parsed.local;domain.value=parsed.domain;}
   preview.textContent='อีเมลที่จะใช้: '+parsed.email;
  }catch(error){preview.textContent=error.message;}
 }
 local.addEventListener('input',update);domain.addEventListener('change',update);update();
}
function authHeaders(){return {'apikey':C.publishableKey,'Content-Type':'application/json'};}
async function submitLogin(e){
  e.preventDefault();const f=e.target;let email;
  try{email=emailChoice(f);}catch(err){return toast(err.message,true);}
  const pass=String(f.elements.password.value||'');if(!pass)return toast('กรุณากรอกรหัสผ่าน',true);
  const btn=f.querySelector('[type=submit]');btn.disabled=true;
  try{
    const r=await fetch(`${C.supabaseUrl}/auth/v1/token?grant_type=password`,{method:'POST',headers:authHeaders(),body:JSON.stringify({email,password:pass})});
    const x=await r.json().catch(()=>({}));
    if(!r.ok)throw Error('เข้าสู่ระบบไม่สำเร็จ กรุณาตรวจอีเมล/รหัสผ่าน หรือเลือกสมัครใช้งาน');
    saveSession(x);await startApp();
  }catch(err){toast(err.message,true);}finally{btn.disabled=false;}
}
async function submitSignup(e){
  e.preventDefault();if(!validConfig())return;
  const f=e.target;let email;try{email=emailChoice(f);}catch(err){return toast(err.message,true);}
  const password=String(f.elements.password.value||'');
  if(password.length<6)return toast('รหัสผ่านต้องยาวอย่างน้อย 6 ตัว',true);
  if(password!==String(f.elements.confirm.value||''))return toast('ยืนยันรหัสผ่านไม่ตรงกัน',true);
  const btn=f.querySelector('[type=submit]');btn.disabled=true;
  try{
    const r=await fetch(`${C.supabaseUrl}/auth/v1/signup?redirect_to=${encodeURIComponent('https://equipment.cnmiblood.com/')}`,{
      method:'POST',headers:authHeaders(),body:JSON.stringify({email,password})
    });
    const x=await r.json().catch(()=>({}));
    if(!r.ok)throw Error(x.msg||x.error_description||x.message||'สมัครไม่ได้ กรุณาตรวจการตั้งค่า Email Provider');
    signupDoneScreen(email);
  }catch(err){toast(err.message,true);}finally{btn.disabled=false;f.elements.password.value='';f.elements.confirm.value='';}
}
function loginFields(mode){const reg=mode==='signup';return `<form id="${reg?'signupForm':'loginForm'}" class="stack">
<div class="field"><label>เลือกหน่วยงานและชื่อผู้ใช้</label><div class="email-pair"><select name="domain" aria-label="เลือกหน่วยงาน"><option value="mahidol.ac.th">มหิดล · @mahidol.ac.th</option><option value="rfs.co.th">BEM (RFS) · @rfs.co.th</option></select><input name="local" autocomplete="username" inputmode="email" required placeholder="username.sur หรือ username.s" aria-label="ชื่ออีเมล ไม่ต้องพิมพ์ @"></div><small class="email-preview" data-email-preview aria-live="polite">ตัวอย่าง: username.sur@mahidol.ac.th</small></div>
<div class="field"><label>${reg?'ตั้งรหัสผ่าน (อย่างน้อย 6 ตัว)':'รหัสผ่าน'}</label><input name="password" type="password" minlength="${reg?6:1}" autocomplete="${reg?'new-password':'current-password'}" required placeholder="กรอกรหัสผ่าน"></div>
${reg?'<div class="field"><label>ยืนยันรหัสผ่าน</label><input name="confirm" type="password" minlength="6" autocomplete="new-password" required placeholder="กรอกรหัสผ่านอีกครั้ง"></div>':''}
<button class="btn primary" type="submit" ${validConfig()?'':'disabled'}>${reg?'สมัครและรับอีเมลยืนยัน':'เข้าสู่ระบบ'}</button></form>`;}
function loginScreen(mode='login'){
  const reg=mode==='signup', configOk=validConfig();
  $('#app').innerHTML=`<main class="login"><section class="panel"><h1>CNMI Equipment Care</h1><p class="muted">ทะเบียนเครื่องมือ · เอกสารรายเดือน · BEM</p>
  ${!configOk?'<p class="message error">กรุณาตั้งค่า Supabase URL และ Publishable Key ใน config.js ก่อน</p>':''}
  <div class="auth-tabs"><button class="btn ${reg?'':'primary'}" type="button" id="gotoLogin">เข้าสู่ระบบ</button><button class="btn ${reg?'primary':''}" type="button" id="gotoSignup">สมัครใช้งาน</button></div>
  ${loginFields(mode)}
  <p class="note">${reg?'ยืนยันอีเมลก่อน จากนั้นเข้าสู่ระบบเพื่อส่งคำขออนุมัติ · ยังเปิดทะเบียนไม่ได้จนกว่า Admin จะอนุมัติ':'ยังไม่มีบัญชี? กด “สมัครใช้งาน” · หากเข้าสู่ระบบไม่ได้ โปรดตรวจรหัสผ่านก่อนสมัครใหม่'}</p>
  ${!reg?`<div class="actions" style="margin-top:10px"><button class="btn" id="googleLogin" ${configOk?'':'disabled'}>Google (บัญชีเดิม)</button></div>`:''}
  </section></main>`;
  $('#gotoLogin').onclick=()=>loginScreen('login');$('#gotoSignup').onclick=()=>loginScreen('signup');
  if(reg){attachEmailPreview($('#signupForm'));$('#signupForm').onsubmit=submitSignup;}else{attachEmailPreview($('#loginForm'));$('#loginForm').onsubmit=submitLogin;$('#googleLogin').onclick=googleLogin;}
}
function signupDoneScreen(email){$('#app').innerHTML=`<main class="login"><section class="panel"><h1>ตรวจอีเมลเพื่อยืนยันบัญชี</h1><p>ส่งคำขอสมัครสำหรับ <b>${esc(email)}</b> แล้ว หากระบบอนุญาตการสมัคร จะมีอีเมลยืนยันส่งไปให้</p><p class="note">กดลิงก์ยืนยันในอีเมล จากนั้นกลับมาเข้าสู่ระบบเพื่อบันทึกคำขอรอ Admin อนุมัติ (การส่งอีเมลขึ้นกับ Supabase Email Provider)</p><button id="afterSignupLogin" class="btn primary">กลับหน้าเข้าสู่ระบบ</button></section></main>`;$('#afterSignupLogin').onclick=()=>loginScreen();}
function pendingScreen(email,status){const rejected=status==='rejected',disabled=status==='approved';$('#app').innerHTML=`<main class="login"><section class="panel"><h1>${rejected?'คำขอไม่ได้รับอนุมัติ':disabled?'บัญชีถูกพักใช้งาน':'รอ Admin อนุมัติ'}</h1><p class="muted">${esc(email)}</p><p>${rejected||disabled?'บัญชีนี้ยังไม่สามารถใช้งานได้ กรุณาติดต่อ Admin เพื่อขอตรวจสอบสิทธิ์':'ยืนยันอีเมลแล้วและส่งคำขอเข้าสู่ระบบเรียบร้อย ยังไม่อนุญาตให้ดูทะเบียนหรือ PDF จนกว่า Admin จะอนุมัติ'}</p><div class="actions"><button class="btn primary" id="checkApproval">ตรวจสถานะอีกครั้ง</button><button class="btn" id="pendingLogout">ออกจากระบบ</button></div></section></main>`;$('#checkApproval').onclick=()=>startApp();$('#pendingLogout').onclick=()=>{resetSession();loginScreen();};}
function googleLogin(){location.href=`${C.supabaseUrl}/auth/v1/authorize?provider=google&redirect_to=${encodeURIComponent(location.href.split('#')[0])}`;}
async function loadData(){const [equip,forms,rules,docs,cases,cal,imports,plans]=await Promise.all([get('eq_equipment?select=*&order=asset_new.asc&limit=1000'),get('eq_forms?select=*&order=code.asc&limit=1000'),get('eq_monthly_rules?select=*&limit=1000'),get('eq_documents?select=*&order=uploaded_at.desc&limit=1000'),get('eq_cases?select=*&order=created_at.desc&limit=1000'),get('eq_cal_specs?select=*&order=created_at.desc&limit=1000'),get('eq_year_imports?select=*&order=imported_at.desc&limit=1000'),get('eq_year_plan_rows?select=*&limit=1000')]);Object.assign(S,{equipment:equip,forms,rules,docs,cases,cal,years:imports,plans});S.members=S.role==='admin'?await get('eq_members?select=email,role,active,approval_status,requested_at,approved_at&order=requested_at.desc&limit=1000'):[];window.EQUIPMENT_REGISTRY=equip;window.FORM_CATALOG=forms;}
async function startApp(){
 try{
  if(!validConfig())return loginScreen();
  const t=await authToken();
  const u=await fetch(`${C.supabaseUrl}/auth/v1/user`,{headers:{apikey:C.publishableKey,Authorization:`Bearer ${t}`}});
  if(!u.ok)throw Error('เข้าสู่ระบบไม่สำเร็จ');
  const user=await u.json();S.email=String(user.email||'').toLowerCase();
  if(!user.email_confirmed_at)throw Error('กรุณายืนยันอีเมลก่อนสมัครใช้งาน');
  let rows=await get(`eq_members?email=eq.${encodeURIComponent(S.email)}&select=role,active,must_change_password,approval_status`);
  if(!rows.length){
    const result=await api('POST','rpc/eq_request_access',{});
    if(result!=='pending'&&result!=='approved'&&result!=='rejected')throw Error('ไม่สามารถส่งคำขอได้');
    rows=await get(`eq_members?email=eq.${encodeURIComponent(S.email)}&select=role,active,must_change_password,approval_status`);
  }
  if(!rows.length)throw Error('ไม่พบคำขอใช้งาน กรุณาติดต่อ Admin');
  const member=rows[0];
  if(!member.active){pendingScreen(S.email,member.approval_status);return;}
  S.role=member.role;
  if(member.must_change_password){changePasswordScreen();return;}
  await api('POST','rpc/eq_touch_login',{}).catch(()=>{});
  await loadData();renderShell();
 }catch(e){resetSession();loginScreen();toast(e.message,true);}
}
function changePasswordScreen(first=true){$('#app').innerHTML=`<main class="login"><section class="panel"><h1>${first?'เปลี่ยนรหัสผ่านครั้งแรก':'เปลี่ยนรหัสผ่าน'}</h1><p class="muted">${esc(S.email)}</p><p class="message">${first?'Admin กำหนดรหัสเริ่มต้นให้แล้ว กรุณาตั้งรหัสใหม่ก่อนใช้งานข้อมูลเครื่องมือ':'กรุณากำหนดรหัสผ่านใหม่ แล้วเข้าสู่ระบบอีกครั้ง'}</p><form id="changeFirstPassForm" class="stack"><div class="field"><label>รหัสผ่านใหม่ (อย่างน้อย 6 ตัว)</label><input name="newpass" type="password" minlength="6" autocomplete="new-password" required placeholder="ตัวเลขล้วน / ตัวอักษร / ผสมกันได้"></div><div class="field"><label>ยืนยันรหัสผ่านใหม่</label><input name="confirm" type="password" minlength="6" autocomplete="new-password" required placeholder="กรอกให้ตรงกัน"></div><button class="btn primary" type="submit">เปลี่ยนรหัสผ่าน</button></form><div class="actions"><button class="btn" id="cancelFirstPass">ออกจากระบบ</button></div><p class="note">รหัสใหม่จะเก็บโดย Supabase Auth ไม่บันทึกไว้ใน Equipment Care หรือ GitHub</p></section></main>`;$('#changeFirstPassForm').onsubmit=submitFirstPasswordChange;$('#cancelFirstPass').onclick=()=>{resetSession();loginScreen();};}
async function submitFirstPasswordChange(e){e.preventDefault();const f=e.target,p=String(f.elements.newpass.value||''),c=String(f.elements.confirm.value||'');if(p.length<6)return toast('รหัสผ่านต้องมีอย่างน้อย 6 ตัว',true);if(p!==c)return toast('รหัสผ่านทั้งสองช่องไม่ตรงกัน',true);const b=f.querySelector('[type=submit]');b.disabled=true;try{const t=await authToken();const r=await fetch(`${C.supabaseUrl}/auth/v1/user`,{method:'PUT',headers:{apikey:C.publishableKey,Authorization:`Bearer ${t}`,'Content-Type':'application/json'},body:JSON.stringify({password:p})});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.msg||j.error_description||j.message||'ไม่สามารถเปลี่ยนรหัสผ่านได้');resetSession();loginScreen();toast('เปลี่ยนรหัสผ่านเรียบร้อย กรุณาเข้าสู่ระบบด้วยรหัสใหม่');}catch(err){toast(err.message,true);b.disabled=false;}finally{f.elements.newpass.value='';f.elements.confirm.value='';}}
function navItems(){return [['home','ภาพรวม'],['registry','ทะเบียน'],['monthly','เอกสารรายเดือน'],['scan','สแกน PDF'],['qr','พิมพ์ QR'],['cal','จุด CAL'],['plans','แผน Y'],['case','งาน BEM'],...(S.role==='admin'?[['admin','สิทธิ์ผู้ใช้']]:[])];}
function renderShell(){const nav=navItems().map(([id,label])=>`<button class="nav ${S.view===id?'active':''}" data-go="${id}">${ico(id)}<span>${label}</span></button>`).join('');$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="side-title">CNMI EQUIPMENT</div>${nav}</aside><div class="main"><header class="top"><div class="brand">Equipment Care <span class="pill good">ONLINE</span></div><div style="text-align:right"><small>${esc(S.email)} (${esc(S.role)})</small> <button class="btn small" id="changePass">เปลี่ยนรหัส</button> <button class="btn small" id="logout">ออก</button></div></header><main class="content" id="page"></main></div></div>`;$('#logout').onclick=()=>{resetSession();loginScreen();};$('#changePass').onclick=()=>changePasswordScreen(false);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{S.view=b.dataset.go;renderShell()});draw();}
const title=(h,p='')=>`<div class="heading"><div><h1>${h}</h1>${p?`<p class="hint">${p}</p>`:''}</div><button class="btn small" id="refresh">↻ รีเฟรช</button></div>`;
function attachRefresh(){const b=$('#refresh');if(b)b.onclick=async()=>{try{await loadData();draw();toast('อัปเดตข้อมูลจาก Supabase แล้ว');}catch(e){toast(e.message,true);}};}
function draw(){const p=$('#page');if(!p)return;const m={home:homeView,registry:registryView,monthly:monthlyView,scan:scanView,qr:qrView,cal:calView,plans:plansView,case:caseView,admin:adminView};p.innerHTML=(m[S.view]||homeView)();attachRefresh();const f=window['mount_'+S.view];if(typeof f==='function')f();}
const eqMap=()=>Object.fromEntries(S.equipment.map(e=>[e.id,e]));const formMap=()=>Object.fromEntries(S.forms.map(f=>[f.id,f]));const fmtEq=id=>{const e=eqMap()[id];return e?`${e.asset_new} · ${e.category_th}`:id};const fmtForm=id=>{const f=formMap()[id];return f?`${f.code||'ไม่มี FM'} · ${f.short_label}`:id};
const opts=(rows,value,label,selected='')=>rows.map(r=>`<option value="${esc(r[value])}" ${selected===r[value]?'selected':''}>${esc(typeof label==='function'?label(r):r[label])}</option>`).join('');
const eqSelect=(name='equipment',selected='')=>`<select name="${name}" required><option value="">เลือกเครื่องมือ…</option>${opts(S.equipment,'id',e=>e.asset_new+' · '+e.category_th,selected)}</select>`;
const formSelect=(name='form',selected='')=>`<select name="${name}" required><option value="">เลือกแบบฟอร์ม…</option>${opts(S.forms,'id',f=>(f.code||'ไม่มี FM')+' · '+f.short_label,selected)}</select>`;
function manualFileName(){const form=$('#docForm');if(!form)return '';const e=S.equipment.find(x=>x.id===form.elements.equipment.value),f=S.forms.find(x=>x.id===form.elements.form.value),month=form.elements.month.value;if(!e||!f||!/^[0-9]{4}-[0-9]{2}$/.test(month))return '';const rev=1+Math.max(0,...S.docs.filter(x=>x.equipment_id===e.id&&x.form_id===f.id&&x.doc_month===month+'-01').map(x=>Number(x.revision)||0));const tidy=s=>String(s||'').replace(/[^A-Za-z0-9_-]/g,'_');const [year,mm]=month.split('-');return `${tidy(e.asset_new)}-${mm}-${year}-${tidy(f.code||f.id)}-R${String(rev).padStart(3,'0')}.pdf`;}
function parseDriveFileId(input){let u;try{u=new URL(String(input||'').trim());}catch{return null;}if(u.protocol!=='https:'||u.hostname!=='drive.google.com')return null;const match=u.pathname.match(/^\/file\/d\/([A-Za-z0-9_-]{10,})(?:\/|$)/);const id=match?match[1]:['/open','/uc'].includes(u.pathname)?u.searchParams.get('id'):null;return id&&/^[A-Za-z0-9_-]{10,}$/.test(id)?id:null;}
function manualDriveUrl(id){return `https://drive.google.com/file/d/${encodeURIComponent(id)}/view`;}
function monthDate(m){return m+'-01';}function currentRules(){return S.rules.filter(r=>r.active&&r.start_month<=monthDate(S.month));}
function docFor(r){return S.docs.find(d=>d.equipment_id===r.equipment_id&&d.form_id===r.form_id&&d.doc_month===monthDate(S.month)&&['stored','linked'].includes(d.status));}
function homeView(){const missing=currentRules().filter(r=>!docFor(r)).length,open=S.cases.filter(c=>!c.closed_at).length;return title('ภาพรวม','ข้อมูลจาก Supabase (ไม่ใช่ข้อมูลจำลอง)')+`<div class="cards"><div class="metric"><b>${S.equipment.length}</b><span>ทะเบียนเครื่องมือ</span></div><div class="metric"><b>${missing}</b><span>เอกสารเดือนนี้ที่ยังไม่ครบ</span></div><div class="metric"><b>${open}</b><span>งานที่ยังเปิดอยู่</span></div><div class="metric"><b>${S.docs.filter(d=>['linked','stored'].includes(d.status)).length}</b><span>เอกสารมีลิงก์</span></div></div><section class="panel"><h3>เริ่มงาน</h3><div class="actions"><button class="btn primary" data-goto="scan">สแกนเอกสาร</button><button class="btn" data-goto="monthly">ตรวจเอกสารรายเดือน</button><button class="btn" data-goto="case">แจ้งเครื่องผิดปกติ</button></div></section><section class="panel"><h3>สถานะการเชื่อมต่อ</h3><p>Supabase: เชื่อมต่อแล้ว • Google Drive: อัปโหลดด้วยมือ (ไม่มีการตรวจสิทธิ์ไฟล์อัตโนมัติ)</p><p class="note">แอปอุณหภูมิเดิมยังไม่เชื่อมสองทาง ห้ามตีความว่าเหตุผิดปกติจากตู้เย็นแสดงครบในระบบนี้</p></section>`;}
function registryView(){const term=S.filter.toLowerCase(),rows=S.equipment.filter(e=>[e.asset_new,e.serial_no,e.inventory_no,e.category_th,e.brand,e.model].join(' ').toLowerCase().includes(term));return title('ทะเบียนเครื่องมือ','ค้นจาก ASSET / Serial / เลขครุภัณฑ์')+`<section class="panel"><div class="toolbar"><input id="search" placeholder="ค้นหาเครื่องมือ…" value="${esc(S.filter)}"><span class="muted">${rows.length} รายการ</span></div><div class="table-wrap"><table><thead><tr><th>ASSET</th><th>เครื่องมือ</th><th>ยี่ห้อ / รุ่น</th><th>Serial</th></tr></thead><tbody>${rows.slice(0,350).map(e=>`<tr><td><b>${esc(e.asset_new)}</b></td><td>${esc(e.category_th)}</td><td>${esc([e.brand,e.model].filter(Boolean).join(' / '))}</td><td>${esc(e.serial_no||'-')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function mount_registry(){$('#search').oninput=e=>{S.filter=e.target.value;const pos=e.target.selectionStart;draw();const i=$('#search');i.focus();i.setSelectionRange(pos,pos);};}
function monthlyView(){const rows=currentRules(),missing=rows.filter(r=>!docFor(r)).length;return title('เอกสารรายเดือน',`เดือน ${S.month} • ต้องส่ง ${rows.length} • ค้าง ${missing}`)+`<section class="panel"><div class="toolbar"><input type="month" id="month" value="${S.month}" style="max-width:220px"><button class="btn" data-goto="qr">พิมพ์ QR ตามเดือน</button></div><div class="list">${rows.length?rows.map(r=>{const d=docFor(r);return `<div class="list-item"><div><b>${esc(fmtEq(r.equipment_id))}</b><small>${esc(fmtForm(r.form_id))}</small></div><span class="pill ${d?'good':'bad'}">${d?(d.status==='linked'?'มีลิงก์':'แนบแล้ว'):'ยังไม่ครบ'}</span></div>`;}).join(''):'<div class="empty">ยังไม่มีข้อกำหนดรายเดือนของเดือนนี้</div>'}</div></section>${['admin','staff'].includes(S.role)?`<section class="panel"><h3>กำหนดให้ต้องส่งทุกเดือน</h3><form id="ruleForm" class="grid2"><div class="field"><label>เครื่องมือ</label>${eqSelect()}</div><div class="field"><label>แบบฟอร์ม</label>${formSelect()}</div><div class="field"><label>เริ่มเดือน</label><input name="start" type="month" value="${S.month}" required></div><div class="field"><label>บันทึกข้อกำหนด</label><button class="btn primary">บังคับส่งทุกเดือน</button></div></form><hr/><h3>จัดการรายการที่กำหนด</h3><div class="list scroll-list">${S.rules.map(r=>`<div class="list-item"><div><b>${esc(fmtEq(r.equipment_id))}</b><small>${esc(fmtForm(r.form_id))} · เริ่ม ${r.start_month.slice(0,7)}</small></div><button class="btn small" data-toggle-rule="${r.id}" data-active="${r.active}">${r.active?'พัก':'เปิด'}</button></div>`).join('')}</div></section>`:''}`;}
function mount_monthly(){$('#month').onchange=e=>{S.month=e.target.value;draw();};const f=$('#ruleForm');if(f)f.onsubmit=async e=>{e.preventDefault();const d=new FormData(f),equipment_id=d.get('equipment'),form_id=d.get('form'),start_month=monthDate(d.get('start'));try{const hit=S.rules.find(r=>r.equipment_id===equipment_id&&r.form_id===form_id);if(hit)await api('PATCH',`eq_monthly_rules?id=eq.${hit.id}`,{start_month,active:true,updated_at:new Date().toISOString()});else await api('POST','eq_monthly_rules',{equipment_id,form_id,start_month,created_by:S.email});await loadData();draw();toast('กำหนดส่งทุกเดือนแล้ว');}catch(err){toast(err.message,true);}};document.querySelectorAll('[data-toggle-rule]').forEach(b=>b.onclick=async()=>{try{await api('PATCH',`eq_monthly_rules?id=eq.${b.dataset.toggleRule}`,{active:b.dataset.active!=='true'});await loadData();draw();}catch(e){toast(e.message,true);}});}
function scanView(){const folderLink=C.driveFolderUrl&&/^https:\/\/drive\.google\.com\/drive\/folders\/[A-Za-z0-9_-]+/.test(C.driveFolderUrl)?C.driveFolderUrl:'https://drive.google.com/drive/u/0/my-drive';return title('สแกนเอกสาร','จากเครื่องสแกน หรือเลือก PDF แล้วใช้เครื่องอ่าน QR/บาร์โค้ด')+`<section class="panel"><h3>1. รับเอกสาร</h3><div class="field"><label>เลือก PDF จากโปรแกรม HP / Canon เดิม</label><input id="scanFile" type="file" accept="application/pdf,.pdf"></div><details><summary>สแกนจากแอปผ่านตัวช่วย Portable (ทดลอง)</summary><p class="note">สำหรับ Windows + WIA Flatbed เท่านั้น ต้องได้รับอนุญาตจาก IT และเปิดตัวช่วยบนคอมเครื่องเดียวกับสแกนเนอร์ก่อน รองรับ 1–12 หน้าโดยกดสแกนทีละหน้า; ADF ยังไม่รองรับ</p><div class="field"><label>รหัสจับคู่จากหน้าต่าง Portable</label><input id="localToken" autocomplete="off" spellcheck="false" placeholder="รหัส 32 ตัว (ไม่ต้องส่งในแชต)"></div><div class="actions"><button class="btn" type="button" id="localConnect">ตรวจพบสแกนเนอร์</button><select id="localDevice" style="max-width:260px" aria-label="เลือกเครื่องสแกน"><option value="">ยังไม่เชื่อม</option></select><button class="btn" type="button" id="localScanPage">สแกน 1 หน้า</button><button class="btn primary" type="button" id="localFinish">จบชุด → สร้าง PDF</button></div><p class="note" id="localStatus">ยังไม่มีภาพสแกน</p></details><div id="scanResult" class="message" style="margin-top:10px">ยังไม่เลือก PDF</div><div class="actions"><button class="btn primary" type="button" id="readQR">อ่าน QR จาก PDF</button></div></section><section class="panel"><h3>2. ยิงบาร์โค้ด / QR บนกระดาษ</h3><div class="field"><label>คลิกช่องนี้ แล้วใช้เครื่องอ่านยิงรหัส (หรือพิมพ์เอง)</label><input id="scanBarcode" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="CN-B-000310-11-2026 หรือ QR ของแอป" aria-describedby="barcodeHelp"></div><div class="actions"><button class="btn primary" type="button" id="applyBarcode">จับคู่จากรหัส</button><button class="btn" type="button" id="focusBarcode">พร้อมยิงรหัส</button></div><p class="note" id="barcodeHelp">เครื่องอ่านต้องส่งข้อมูลเหมือนแป้นพิมพ์ USB/HID และรองรับ QR หากสติกเกอร์เป็น QR แบบ 2 มิติ • กด Enter เพื่อจับคู่ได้ทันที</p><div id="barcodeStatus" role="status" class="message">ยังไม่ได้ยิงรหัส</div></section><section class="panel"><h3>3. ตรวจข้อมูล / ตั้งชื่อ PDF</h3><form id="docForm"><div class="grid2"><div class="field"><label>เครื่องมือ</label>${eqSelect()}</div><div class="field"><label>แบบฟอร์ม</label>${formSelect()}</div><div class="field"><label>เดือนที่บันทึก</label><input name="month" type="month" value="${S.month}" required></div><div class="field"><label>ชื่อผู้สแกน</label><input name="actor" required placeholder="ชื่อผู้ปฏิบัติงาน"></div></div><p class="message" id="proposedName">เลือกเครื่อง ฟอร์ม และเดือนเพื่อตั้งชื่อไฟล์</p><div class="actions"><button class="btn primary" id="downloadNamed" type="button">ดาวน์โหลด PDF ชื่อใหม่</button><a class="btn" href="${esc(folderLink)}" target="_blank" rel="noopener noreferrer">เปิด Google Drive</a></div><p class="note">ยังใช้ Google Drive แบบอัปโหลดด้วยมือ ไม่ใช้ Google Cloud API: ดาวน์โหลด PDF ชื่อใหม่ → อัปโหลดด้วยเมลมหิดล → คัดลอกลิงก์กลับมาวางด้านล่าง</p><hr/><div class="field"><label>ลิงก์ PDF ที่อัปโหลดใน Google Drive แล้ว</label><input name="drive_link" type="url" placeholder="https://drive.google.com/file/d/.../view" required></div><label class="doc-label"><input type="checkbox" name="confirmed" required><span>ยืนยันว่าอัปโหลดไฟล์ถูกเครื่อง/ฟอร์ม/เดือนแล้ว และลิงก์เปิดได้</span></label><button class="btn primary" id="savePdf" type="submit">บันทึกลิงก์ในทะเบียน</button><p class="note">ข้อมูลการสแกนและบาร์โค้ดไม่ใช่หลักฐานว่าไฟล์อยู่ใน Drive จนกว่าจะอัปโหลดและยืนยันลิงก์เอง</p></form></section><section class="panel"><h3>เอกสารในทะเบียน</h3><div class="list scroll-list">${S.docs.filter(d=>['stored','linked'].includes(d.status)).slice(0,70).map(d=>`<div class="list-item"><div><b>${esc(d.file_name)}</b><small>R${d.revision} · ${esc(d.uploader_email)} · ${d.status==='linked'?'ลิงก์จากผู้ใช้':'Drive API เดิม'}</small></div><button class="btn small" data-download="${d.id}" type="button">เปิด</button></div>`).join('')||'<div class="empty">ยังไม่มีเอกสาร</div>'}</div></section>`;}
function mount_scan(){
 const fileInput=$('#scanFile'),doc=$('#docForm'),msg=$('#scanResult'),status=$('#barcodeStatus');
 const proposal=()=>{$('#proposedName').textContent=manualFileName()||'เลือกเครื่อง ฟอร์ม และเดือนเพื่อตั้งชื่อไฟล์';};
 const update=()=>{proposal();};
 doc.elements.equipment.addEventListener('change',update);doc.elements.form.addEventListener('change',update);doc.elements.month.addEventListener('change',update);proposal();
 fileInput.onchange=()=>{S.uploadFile=fileInput.files?.[0]||null;S.scanInfo=null;S.embeddedScan=null;S.scanConflict=false;doc.elements.equipment.value='';doc.elements.form.value='';$('#scanBarcode').value='';status.className='message';status.textContent='ยังไม่ได้ยิงรหัสสำหรับ PDF นี้';proposal();msg.className='message';msg.textContent=S.uploadFile?`PDF: ${S.uploadFile.name}`:'ยังไม่เลือกไฟล์';};
 function applyMatch(data,source){
   if(S.scanConflict)return toast('PDF มี QR จากหลายเครื่อง ต้องแยกไฟล์ก่อน',true);
   if(!data.ok){status.className='message error';status.textContent=data.message;return;}
   if(S.embeddedScan && (S.embeddedScan.target!==data.asset || (S.embeddedScan.formId && data.formId && S.embeddedScan.formId!==data.formId) || (S.embeddedScan.period && data.month && S.embeddedScan.period!==data.month))){status.className='message error';status.textContent='รหัสที่ยิงไม่ตรงกับ QR ใน PDF กรุณาตรวจเอกสาร';return;}
   doc.elements.equipment.value=data.equipmentId;
   if(data.formId)doc.elements.form.value=data.formId;
   else doc.elements.form.value='';
   if(data.month)doc.elements.month.value=data.month;
   S.scanInfo={type:'equipment',target:data.asset,formId:data.formInCode?data.formId:'',period:data.monthInCode?data.month:'',source};
   status.className='message';status.textContent=`จับคู่: ${data.asset}${data.month?' / '+data.month:''}${data.formId?' / '+fmtForm(data.formId):' • โปรดเลือกแบบฟอร์ม'}`;
   msg.textContent=`ได้รหัสเครื่องมือแล้วจาก${source==='barcode'?'เครื่องอ่าน':'QR ใน PDF'}`;
   proposal();
 }
 const parseCode=value=>window.CNMI_BARCODE.parse(value,S.equipment,S.forms,S.rules,doc.elements.month.value);
 const readCode=()=>applyMatch(parseCode($('#scanBarcode').value),'barcode');
 $('#applyBarcode').onclick=readCode;
 $('#scanBarcode').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();readCode();}});
 $('#focusBarcode').onclick=()=>{$('#scanBarcode').focus();$('#scanBarcode').select();};
 $('#readQR').onclick=async()=>{
   if(!S.uploadFile)return toast('ต้องเลือก PDF หรือสแกนเป็น PDF ก่อน',true);
   msg.className='message';msg.textContent='กำลังอ่าน QR ใน PDF…';
   try{
     const read=await window.CNMI_SCAN.scan(S.uploadFile);
     if(read.conflict){S.scanInfo=null;S.embeddedScan=null;S.scanConflict=true;msg.className='message error';msg.textContent='พบ QR หลายเครื่องใน PDF เดียว กรุณาสแกนแยกไฟล์';return;}
     const data=window.CNMI_SCAN.parsePayload(read.value);
     if(['monthly','permanent'].includes(data.mode)&&data.type==='equipment'){
       const result=parseCode(read.value);
       if(result.ok){S.embeddedScan={target:result.asset,formId:result.formId,period:data.period||''};applyMatch(result,'pdf-qr');return;}
     }
     S.embeddedScan=null;S.scanInfo=null;msg.className='message error';msg.textContent='อ่าน QR ไม่สำเร็จหรือไม่ตรงทะเบียน → ใช้เครื่องอ่านบาร์โค้ดยิงรหัสแทนได้';
     $('#scanBarcode').focus();
   }catch(e){S.embeddedScan=null;S.scanInfo=null;msg.className='message error';msg.textContent='อ่าน QR ไม่ได้: '+e.message+' — ลองยิงด้วยเครื่องอ่าน';}
 };
 $('#downloadNamed').onclick=()=>{
   if(!S.uploadFile)return toast('ต้องมี PDF ก่อน',true);
   if(S.scanConflict)return toast('PDF มี QR ขัดแย้ง ไม่อนุญาตให้ดาวน์โหลดเพื่อตั้งชื่ออัตโนมัติ',true);
   const e=S.equipment.find(x=>x.id===doc.elements.equipment.value),fid=doc.elements.form.value,period=doc.elements.month.value;
   const checks=[S.scanInfo&&{target:S.scanInfo.target,formId:S.scanInfo.formId,period:S.scanInfo.period}, S.embeddedScan];
   if(checks.some(x=>x && (!e||x.target!==e.asset_new||(x.formId&&x.formId!==fid)||(x.period&&x.period!==period))))return toast('ข้อมูลในฟอร์มไม่ตรงกับ QR/บาร์โค้ด ห้ามตั้งชื่อผิดเครื่อง',true);
   const name=manualFileName();if(!name)return toast('เลือกเครื่อง ฟอร์ม และเดือนก่อน',true);
   const url=URL.createObjectURL(S.uploadFile),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);toast('ได้ไฟล์ชื่อ '+name+' แล้วให้อัปโหลดเข้า Drive');
 };
 doc.onsubmit=async e=>{
   e.preventDefault();if(S.scanConflict)return toast('PDF มี QR ขัดแย้ง ต้องแยกไฟล์ก่อน',true);
   const d=new FormData(doc),id=String(d.get('equipment')||''),fid=String(d.get('form')||''),month=String(d.get('month')||''),actor=String(d.get('actor')||'').trim(),driveId=parseDriveFileId(d.get('drive_link'));
   if(!id||!fid||!month||!actor)return toast('กรุณาระบุเครื่อง ฟอร์ม เดือน และชื่อผู้ปฏิบัติงาน',true);
   if(!driveId)return toast('ลิงก์ไม่ถูกต้อง ต้องเป็นลิงก์ PDF จาก Google Drive',true);
   if(d.get('confirmed')!=='on')return toast('กรุณายืนยันว่าอัปโหลด PDF เข้า Drive แล้ว',true);
   if(S.scanInfo){const eq=S.equipment.find(x=>x.id===id);
     if(!eq||S.scanInfo.target!==eq.asset_new)return toast('ASSET ที่ยิงไม่ตรงกับเครื่องที่เลือก',true);
     if(S.scanInfo.formId&&S.scanInfo.formId!==fid)return toast('ฟอร์มไม่ตรงกับรหัสที่ยิง',true);
     if(S.scanInfo.period&&S.scanInfo.period!==month)return toast('เดือนไม่ตรงกับรหัสที่ยิง',true);
   }
   if(S.embeddedScan){const eq=S.equipment.find(x=>x.id===id);
     if(!eq||S.embeddedScan.target!==eq.asset_new||S.embeddedScan.formId&&S.embeddedScan.formId!==fid||S.embeddedScan.period&&S.embeddedScan.period!==month)return toast('ข้อมูลไม่ตรงกับ QR ที่อ่านจาก PDF',true);
   }
   const b=$('#savePdf');b.disabled=true;b.textContent='กำลังบันทึก…';
   try{const res=await api('POST','rpc/eq_register_drive_link',{p_equipment:id,p_form:fid,p_month:monthDate(month),p_drive_file_id:driveId,p_actor:actor});const saved=res?.[0];if(!saved?.doc_id)throw Error('Supabase ไม่ส่งรหัสกลับมา ตรวจรายการก่อนกดซ้ำ');await loadData();S.uploadFile=null;S.localPages=[];draw();toast('บันทึกลิงก์สำเร็จ: '+saved.doc_name);}
   catch(err){toast(err.message,true);b.disabled=false;b.textContent='บันทึกลิงก์ในทะเบียน';}
 };
 // Optional local bridge. User must launch the helper and pair explicitly.
 const localStatus=$('#localStatus');
 $('#localConnect').onclick=async()=>{try{const token=$('#localToken').value;const info=await window.CNMI_LOCAL_SCAN.devices(token);S.localDevices=info.devices||[];$('#localDevice').innerHTML='<option value="">เลือกสแกนเนอร์</option>'+S.localDevices.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('');localStatus.textContent=`พบ ${S.localDevices.length} เครื่อง`;if(S.localDevices.length===1)$('#localDevice').value=S.localDevices[0].id;}catch(e){localStatus.textContent='เชื่อมต่อไม่ได้: '+e.message;toast(e.message,true);}};
 $('#localScanPage').onclick=async()=>{const token=$('#localToken').value,id=$('#localDevice').value;if(!id)return toast('เลือกเครื่องสแกนเนอร์ก่อน',true);const b=$('#localScanPage');b.disabled=true;localStatus.textContent='กำลังสแกนภาพจาก Flatbed…';try{const page=await window.CNMI_LOCAL_SCAN.scanPage(token,id);S.localPages.push(page);localStatus.textContent=`สแกนแล้ว ${S.localPages.length} หน้า • ${page.scanner}`;}catch(e){toast(e.message,true);localStatus.textContent=e.message;}finally{b.disabled=false;}};
 $('#localFinish').onclick=async()=>{if(!S.localPages.length)return toast('สแกนอย่างน้อย 1 หน้าก่อน',true);try{const blob=await window.CNMI_LOCAL_SCAN.createPdf(S.localPages),name='CNMI_SCAN_'+Date.now()+'.pdf';S.uploadFile=new File([blob],name,{type:'application/pdf'});S.localPages=[];S.scanInfo=null;S.embeddedScan=null;S.scanConflict=false;doc.elements.equipment.value='';doc.elements.form.value='';$('#scanBarcode').value='';status.className='message';status.textContent='ยังไม่ได้ยิงรหัสสำหรับ PDF นี้';proposal();msg.className='message';msg.textContent=`สร้าง PDF จากตัวช่วยแล้ว: ${name} • กดอ่าน QR หรือยิงบาร์โค้ดต่อ`;localStatus.textContent='สร้าง PDF แล้ว • พร้อมยิงบาร์โค้ด';$('#scanBarcode').focus();toast('สร้าง PDF สำเร็จ');}catch(e){toast(e.message,true);}};
 document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>openDriveFile(b.dataset.download));
}
async function openDriveFile(id){const doc=S.docs.find(x=>x.id===id);if(!doc)return toast('ไม่พบรายการ',true);if(doc.status==='linked'){if(!doc.drive_file_id)return toast('รายการยังไม่มีลิงก์',true);window.open(manualDriveUrl(doc.drive_file_id),'_blank','noopener,noreferrer');return;}try{const jwt=await authToken();const r=await fetch(`${C.supabaseUrl}/functions/v1/drive-document?id=${encodeURIComponent(id)}`,{headers:{apikey:C.publishableKey,Authorization:`Bearer ${jwt}`}});if(!r.ok){const j=await r.json();throw Error(j.error||'เปิดไฟล์ไม่ได้');}const blob=await r.blob(),url=URL.createObjectURL(blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),120000);}catch(e){toast(e.message,true);}}
function qrView(){const rows=currentRules().filter(r=>!!eqMap()[r.equipment_id]&&!!formMap()[r.form_id]),missing=rows.filter(r=>!docFor(r));return title('พิมพ์ QR เป็นชุด',`สติกเกอร์ม้วน 20×25 มม. · QR 15×15 มม. · เดือน ${S.month}`)+`<section class="panel"><div class="toolbar"><input type="month" id="qrMonth" value="${S.month}" style="max-width:220px"><button class="btn" id="allQr">เลือกทั้งหมด</button><button class="btn" id="missingQr">เฉพาะค้าง (${missing.length})</button><button class="btn" id="clearQr">ล้าง</button></div><div class="list scroll-list">${rows.map(r=>{const id=r.id,checked=S.selected.has(id);return `<label class="doc-label"><input type="checkbox" data-qrcheck="${id}" ${checked?'checked':''}><div class="fill"><b>${esc(fmtEq(r.equipment_id))}</b><small>${esc(fmtForm(r.form_id))}</small></div><span class="pill ${docFor(r)?'good':'bad'}">${docFor(r)?'ครบ':'ค้าง'}</span></label>`;}).join('')||'<div class="empty">ต้องกำหนดให้ส่งรายเดือนก่อนจึงจะพิมพ์เป็นชุดได้</div>'}</div><hr/><div class="actions"><button class="btn primary" id="printQR">พิมพ์สติกเกอร์ที่เลือก (<span id="qrCount">${S.selected.size}</span>)</button></div><p class="note">พิมพ์ครั้งเดียวต่อเนื่อง 1 ดวงต่อหน้า เครื่องพิมพ์ม้วนต้องตั้ง 20 × 25 มม. / Actual size 100% ช่องว่าง 0.2 มม. ตั้งที่ Driver ของเครื่องพิมพ์จริง</p></section>`;}
function mount_qr(){const reset=()=>{S.selected=new Set();draw();};$('#qrMonth').onchange=e=>{S.month=e.target.value;reset();};$('#allQr').onclick=()=>{S.selected=new Set(currentRules().map(r=>r.id));draw();};$('#missingQr').onclick=()=>{S.selected=new Set(currentRules().filter(r=>!docFor(r)).map(r=>r.id));draw();};$('#clearQr').onclick=reset;document.querySelectorAll('[data-qrcheck]').forEach(c=>c.onchange=()=>{if(c.checked)S.selected.add(c.dataset.qrcheck);else S.selected.delete(c.dataset.qrcheck);$('#qrCount').textContent=S.selected.size;});$('#printQR').onclick=()=>{const items=currentRules().filter(r=>S.selected.has(r.id));if(!items.length)return toast('ยังไม่ได้เลือกสติกเกอร์',true);if(items.length>150)return toast('หนึ่งรอบพิมพ์ได้ไม่เกิน 150 ดวง',true);const pages=items.map(r=>{const e=eqMap()[r.equipment_id],f=formMap()[r.form_id];const payload=['ECM1',f.id,'E',e.asset_new,S.month].join('|');const qr=window.CNMI_QR.svg(payload);return `<div class="label"><div class="code">${qr}</div><div class="caption"><b>${esc(f.code||f.id)}</b><span>${esc(f.short_label)}</span><strong>${esc(e.asset_new)} · ${S.month}</strong></div></div>`;}).join('');const w=window.open('','_blank');if(!w)return toast('เบราว์เซอร์บล็อกหน้าต่างพิมพ์ กรุณาอนุญาต Pop-ups',true);w.document.open();w.document.write(`<!doctype html><html><head><title>CNMI QR Roll</title><style>@page{size:20mm 25mm;margin:0}html,body{margin:0;padding:0}.label{width:20mm;height:25mm;overflow:hidden;page-break-after:always;break-after:page;display:flex;align-items:center;flex-direction:column;justify-content:flex-start;background:#fff;color:#000}.code{height:15mm;width:15mm;margin-top:.3mm}.code svg{width:15mm!important;height:15mm!important}.caption{width:19.5mm;text-align:center;display:flex;flex-direction:column;line-height:1.0;gap:.35mm;margin-top:.35mm;font-family:Arial,sans-serif}.caption b{font-size:5pt;overflow:hidden;white-space:nowrap}.caption span{font-size:4.8pt;white-space:nowrap;overflow:hidden}.caption strong{font-size:4.6pt;white-space:nowrap;overflow:hidden}@media screen{body{background:#ddd}.label{margin:10px auto;box-shadow:0 0 2px #777}}@media print{.label:last-child{page-break-after:auto;break-after:auto}}</style></head><body>${pages}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),400);};}
function calView(){return title('จุด Calibration ของแล็บ','แล็บกำหนดงานที่ใช้และจุดสอบเทียบ BEM อ่านได้')+`<section class="panel"><form id="calForm"><div class="grid2"><div class="field"><label>เครื่องมือ</label>${eqSelect()}</div><div class="field"><label>ใช้กับงานอะไร</label><input name="purpose" required placeholder="ระบุงานที่ใช้จริง"></div><div class="field"><label>พารามิเตอร์</label><select name="parameter"><option value="volume">ปริมาตร</option><option value="time">เวลา</option><option value="temperature">อุณหภูมิ</option><option value="speed">ความเร็วรอบ</option><option value="other">อื่น ๆ</option></select></div><div class="field"><label>หน่วย</label><input name="unit" required placeholder="เช่น µL, s, °C, rpm"></div></div><div class="field"><label>จุดสอบเทียบ (หนึ่งจุดต่อหนึ่งบรรทัด)</label><textarea name="points" rows="5" required placeholder="ระบุค่าที่ต้องการสอบเทียบ ไม่กำหนดให้ล่วงหน้า"></textarea></div>${['admin','staff'].includes(S.role)?'<button class="btn primary">บันทึกข้อกำหนดใหม่ (Revision)</button>':'<p class="note">เฉพาะแล็บ/Admin มีสิทธิ์แก้ไข</p>'}</form></section><section class="panel"><h3>ข้อกำหนดที่บันทึกแล้ว</h3><div class="list">${S.cal.slice(0,100).map(x=>`<div class="list-item"><div><b>${esc(fmtEq(x.equipment_id))} · R${x.revision}</b><small>${esc(x.purpose)} · ${esc(x.parameter)} (${esc(x.unit)}): ${esc((x.points||[]).join(', '))}</small></div></div>`).join('')||'<div class="empty">ยังไม่มีข้อกำหนด</div>'}</div></section>`;}
function mount_cal(){const f=$('#calForm');if(!['admin','staff'].includes(S.role))return;f.onsubmit=async e=>{e.preventDefault();const d=new FormData(f),id=d.get('equipment'),purpose=String(d.get('purpose')||'').trim(),unit=String(d.get('unit')||'').trim(),points=String(d.get('points')||'').split('\n').map(x=>x.trim()).filter(Boolean);if(!id||!purpose||!unit||!points.length)return toast('กรอกข้อมูล CAL ให้ครบ',true);const rev=Math.max(0,...S.cal.filter(x=>x.equipment_id===id).map(x=>x.revision))+1;try{await api('POST','eq_cal_specs',{equipment_id:id,revision:rev,purpose,unit,parameter:d.get('parameter'),points,actor_email:S.email});await loadData();draw();toast('บันทึกจุด CAL แล้ว');}catch(err){toast(err.message,true);}};}
function plansView(){return title('นำเข้าแผน Y ประจำปี','อัปโหลด Excel แล้วตรวจรายการก่อนบันทึก ไม่ทับแผนปีเก่า')+`<section class="panel"><form id="yForm"><div class="grid2"><div class="field"><label>ปี ค.ศ. ของแผน</label><input name="year" type="number" min="2020" max="2100" value="${new Date().getFullYear()+1}" required></div><div class="field"><label>ประเภทแผน</label><select name="kind"><option value="PM">PM</option><option value="CAL">Calibration</option></select></div><div class="field"><label>ไฟล์ Excel จาก BEM (.xlsx)</label><input name="file" type="file" accept=".xlsx" required></div><div class="field"><label>อ่านข้อมูล</label><button class="btn" type="submit">แสดงตัวอย่าง</button></div></div></form><div id="yPreview">${S.pendingRows.length?previewPlans():''}</div></section><section class="panel"><h3>ไฟล์แผนที่นำเข้าแล้ว</h3>${S.years.slice(0,70).map(i=>`<div class="list-item"><div><b>${i.plan_year} · ${esc(i.plan_kind)} · ${esc(i.file_name)}</b><small>${i.row_count} จุดแผน · ${esc(i.imported_by)}</small></div></div>`).join('')||'<div class="empty">ยังไม่มีแผน</div>'}</section>`;}
function nameMonth(h){const z=String(h).toLowerCase().trim().replace(/\./g,'');const arr=[['มกราคม','มค','jan','january'],['กุมภาพันธ์','กพ','feb','february'],['มีนาคม','มีค','mar','march'],['เมษายน','เมย','apr','april'],['พฤษภาคม','พค','may'],['มิถุนายน','มิย','jun','june'],['กรกฎาคม','กค','jul','july'],['สิงหาคม','สค','aug','august'],['กันยายน','กย','sep','september'],['ตุลาคม','ตค','oct','october'],['พฤศจิกายน','พย','nov','november'],['ธันวาคม','ธค','dec','december']];return arr.findIndex(a=>a.some(v=>z===v||z===v+'-Y'))+1;}
function matchEquipment(value){const x=String(value||'').trim().toUpperCase().replace(/\s+/g,'');if(!x)return null;for(const key of ['asset_new','inventory_no','serial_no']){const matches=S.equipment.filter(e=>String(e[key]||'').trim().toUpperCase().replace(/\s+/g,'')===x);if(matches.length===1)return matches[0];if(matches.length>1)return null;}return null;}
function previewPlans(){const found=S.pendingRows.filter(r=>r.equipment_id),missing=S.pendingRows.filter(r=>!r.equipment_id);return `<div class="message">พบ ${found.length} จุดแผน · ต้องตรวจสอบ ${missing.length} รายการ (จะไม่สร้างเครื่องมืออัตโนมัติ)</div>${missing.length?`<details><summary>ดูรายการที่จับคู่ไม่ได้</summary><p>${missing.slice(0,30).map(x=>esc(x.raw)).join(', ')}</p></details>`:''}${found.length?'<button class="btn primary" id="saveY">ยืนยันนำเข้ารายการที่จับคู่ได้</button>':''}`;}
function mount_plans(){const f=$('#yForm');f.onsubmit=async e=>{e.preventDefault();if(!['admin','bem'].includes(S.role))return toast('เฉพาะ BEM/Admin นำเข้าแผนได้',true);const d=new FormData(f),file=d.get('file');try{const sheet=(await window.CNMI_XLSX.load(file))[0];if(!sheet)throw Error('ไม่พบข้อมูล Excel');let headIndex=sheet.rows.findIndex(r=>r.values.some(v=>/asset|ครุภัณฑ์|serial/i.test(String(v||''))) && r.values.some(v=>nameMonth(v)>0));if(headIndex<0)throw Error('ไม่พบแถวหัวตารางที่มี ASSET/ครุภัณฑ์/Serial และชื่อเดือน ขอไฟล์ที่มีคอลัมน์เหล่านี้ก่อน');const headers=sheet.rows[headIndex].values,assetIdx=headers.findIndex(x=>/asset|ครุภัณฑ์|serial/i.test(String(x||'')));const months=headers.map(nameMonth);const results=[];for(const r of sheet.rows.slice(headIndex+1)){const raw=r.values[assetIdx];if(!raw)continue;for(let c=0;c<months.length;c++){if(!months[c]||!/^y$/i.test(String(r.values[c]||'').trim()))continue;results.push({raw:String(raw),equipment_id:matchEquipment(raw)?.id||null,plan_month:months[c]});}}if(!results.length)throw Error('ไม่พบ Y ในคอลัมน์เดือนของไฟล์');S.pendingRows=results;S.importName=file.name;S.importYear=Number(d.get('year'));S.importKind=String(d.get('kind'));$('#yPreview').innerHTML=previewPlans();$('#saveY')?.addEventListener('click',saveY); }catch(err){toast(err.message,true);}};}
async function saveY(){const ok=S.pendingRows.filter(r=>r.equipment_id);if(!ok.length)return;const btn=$('#saveY');btn.disabled=true;try{const imports=await api('POST','eq_year_imports',{plan_year:S.importYear,plan_kind:S.importKind,file_name:S.importName,imported_by:S.email,row_count:ok.length});const iid=imports[0]?.id;if(!iid)throw Error('สร้างประวัติ Import ไม่สำเร็จ');const rows=ok.map(r=>({import_id:iid,equipment_id:r.equipment_id,plan_month:r.plan_month}));await api('POST','eq_year_plan_rows',rows);S.pendingRows=[];await loadData();draw();toast('นำเข้าแผน Y สำเร็จ '+rows.length+' รายการ');}catch(e){btn.disabled=false;toast(e.message,true);}}
function caseView(){return title('เหตุเครื่องมือผิดปกติ / BEM','หนึ่งเครื่องมือมีเคสเปิดอยู่ได้เพียงหนึ่งเคส')+`<section class="panel"><form id="caseForm"><div class="field"><label>เครื่องมือ</label>${eqSelect()}</div><div class="field"><label>อาการ / เหตุผิดปกติ</label><textarea name="description" rows="2" required placeholder="ระบุอาการที่พบ"></textarea></div>${['admin','staff','bem'].includes(S.role)?'<button class="btn primary">เปิดเหตุใหม่</button>':''}</form></section><section class="panel"><h3>รายการติดตาม</h3><div class="list">${S.cases.slice(0,100).map(c=>`<div class="list-item"><div><b>${esc(fmtEq(c.equipment_id))}</b><small>${esc(c.description)}</small><small>${esc(c.bem_actor_first||'')} · ${esc(c.bem_note||'')}</small></div><div><span class="status ${c.closed_at?'closed':'open'}">${esc(c.status)}</span>${!c.closed_at&&['admin','bem'].includes(S.role)?`<button class="btn small" data-case="${c.id}" style="display:block;margin-top:8px">อัปเดต</button>`:''}</div></div>`).join('')||'<div class="empty">ยังไม่มีเคส</div>'}</div></section><div id="caseUpdate" class="panel hide"></div>`;}
function mount_case(){const f=$('#caseForm');f.onsubmit=async e=>{e.preventDefault();const d=new FormData(f),equipment_id=d.get('equipment'),description=String(d.get('description')||'').trim();if(S.cases.some(c=>c.equipment_id===equipment_id&&!c.closed_at))return toast('เครื่องนี้มีเคสเปิดอยู่แล้ว โปรดอัปเดตเคสเดิม',true);try{await api('POST','eq_cases',{equipment_id,description,opened_by_email:S.email});await loadData();draw();toast('เปิดเหตุแล้ว');}catch(err){toast('ไม่สามารถเปิดเคส (อาจมีเคสเปิดพร้อมกัน): '+err.message,true);}};document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{const c=S.cases.find(x=>x.id===b.dataset.case),el=$('#caseUpdate');el.classList.remove('hide');el.innerHTML=`<h3>อัปเดตเคส: ${esc(fmtEq(c.equipment_id))}</h3><form id="updateCase"><div class="grid2"><div class="field"><label>สถานะ</label><select name="status"><option value="checking">รับเรื่อง / ตรวจสอบ</option><option value="repairing">กำลังซ่อม</option><option value="ready">พร้อมใช้งาน / ปิดเคส</option><option value="cancelled">ยกเลิก / ปิดเคส</option></select></div><div class="field"><label>ชื่อ BEM (บังคับ)</label><input name="first" required></div><div class="field"><label>นามสกุล (ไม่บังคับ)</label><input name="last"></div><div class="field"><label>รายละเอียด</label><input name="note" required></div></div><button class="btn primary">บันทึกการดำเนินงาน</button></form>`;el.scrollIntoView({behavior:'smooth',block:'start'});$('#updateCase').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);try{await api('PATCH',`eq_cases?id=eq.${c.id}`,{status:d.get('status'),bem_actor_first:String(d.get('first')).trim(),bem_actor_last:String(d.get('last')).trim()||null,bem_note:String(d.get('note')).trim()});await loadData();draw();toast('BEM อัปเดตสถานะแล้ว');}catch(err){toast(err.message,true);}};});}
function adminView(){
 if(S.role!=='admin')return '<p>ไม่มีสิทธิ์</p>';
 const pending=S.members.filter(x=>x.approval_status==='pending'&&!x.active);
 const rows=pending.map(x=>`<div class="list-item" style="gap:12px;align-items:center"><div><b>${esc(x.email)}</b><small>บทบาท: ${esc(x.role==='bem'?'BEM':'เจ้าหน้าที่แล็บ')} · สมัครเมื่อ ${esc(x.requested_at||'-')}</small></div><div class="actions"><button class="btn primary small" data-review="approve" data-email="${esc(x.email)}">อนุมัติ</button><button class="btn small" data-review="reject" data-email="${esc(x.email)}">ไม่อนุมัติ</button></div></div>`).join('');
 return title('อนุมัติผู้ใช้งาน',`รอพิจารณา ${pending.length} บัญชี`)+
 `<section class="panel"><h3>รายการสมัครใหม่</h3><div class="list">${rows||'<p class="muted">ยังไม่มีคำขอรออนุมัติ</p>'}</div><p class="note">มหิดล = staff · RFS = bem · สมัครเองและยืนยันอีเมลก่อน · ผู้สมัครไม่สามารถกำหนด Admin ให้ตัวเองได้</p></section>
 <section class="panel"><h3>ผู้ใช้งานในระบบ</h3><div class="list">${S.members.map(x=>`<div class="list-item"><div><b>${esc(x.email)}</b><small>${esc(x.role)} · ${esc(x.approval_status||'approved')} · ${x.active?'ใช้งานได้':'ยังไม่ได้รับสิทธิ์'}</small></div></div>`).join('')||'<p>ยังไม่มีสมาชิก</p>'}</div></section>`;
}
function mount_admin(){
 document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{
  const email=b.dataset.email,action=b.dataset.review;
  if(!['approve','reject'].includes(action)||!confirm(`${action==='approve'?'อนุมัติ':'ไม่อนุมัติ'} บัญชี ${email} ใช่หรือไม่?`))return;
  b.disabled=true;
  try{
   await api('POST','rpc/eq_review_registration',{p_email:email,p_action:action});
   await loadData();draw();toast(action==='approve'?'อนุมัติบัญชีเรียบร้อย':'บันทึกการไม่อนุมัติแล้ว');
  }catch(err){toast(err.message,true);b.disabled=false;}
 });
}
async function init(){if(location.hash.includes('access_token=')){const raw=new URLSearchParams(location.hash.slice(1));const access_token=raw.get('access_token'),refresh_token=raw.get('refresh_token');if(access_token&&refresh_token){saveSession({access_token,refresh_token,expires_in:Number(raw.get('expires_in')||3600)});history.replaceState({},'',location.pathname+location.search);}}loadSession();if(S.token)await startApp();else loginScreen();}
init().catch(e=>{loginScreen();toast(e.message,true)});
